import React, { useState, useEffect, useMemo } from 'react';
import { Flow } from 'flow-sdk';
import { SectionLabel, PillButton, RangeSlider } from './components/Primitives';
import { FilterPanel } from './components/FilterPanel';
import { FilterCarousel } from './components/FilterCarousel';
import { ImagePreview } from './components/ImagePreview';
import { FilterType, FILTERS } from './constants';

export default function App() {
  const [selectedMedia, setSelectedMedia] = useState<{ mediaId: string; base64: string; mimeType: string } | null>(null);
  const [activeFilterId, setActiveFilterId] = useState<FilterType>(FILTERS[0].id);
  const [intensity, setIntensity] = useState(FILTERS[0].defaultIntensity);
  const [isSaving, setIsSaving] = useState(false);

  // Global CSS Injection for Flow Design System
  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { height: 6px; width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; letter-spacing: 0.1px; -webkit-font-smoothing: antialiased; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleSelectImage = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      setSelectedMedia(media);
    } catch (err) {
      console.error('Image selection failed:', err);
    }
  };

  const activeFilter = useMemo(() => 
    FILTERS.find(f => f.id === activeFilterId) || FILTERS[0]
  , [activeFilterId]);

  const handleFilterChange = (id: FilterType) => {
    const filter = FILTERS.find(f => f.id === id);
    if (filter) {
      setActiveFilterId(id);
      setIntensity(filter.defaultIntensity);
    }
  };

  const handleSave = async () => {
    if (!selectedMedia) return;
    setIsSaving(true);
    try {
      // Create a canvas to apply the filter and save
      const img = new Image();
      img.src = `data:${selectedMedia.mimeType};base64,${selectedMedia.base64}`;
      await new Promise((resolve) => (img.onload = resolve));

      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.filter = activeFilter.getStyle(intensity);
        ctx.drawImage(img, 0, 0);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        await Flow.save({
          base64,
          mimeType: 'image/jpeg',
          name: `${selectedMedia.name}_${activeFilterId}`
        });
      }
    } catch (err) {
      console.error('Save failed:', err);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="flex h-full w-full bg-[#0e0e0e] overflow-hidden">
      {/* Left Content Area */}
      <div className="flex-1 flex flex-col min-w-0 h-full relative">
        <div className="flex-1 min-h-0 flex items-center justify-center p-8">
          <ImagePreview 
            media={selectedMedia} 
            filterStyle={activeFilter.getStyle(intensity)}
            onSelect={handleSelectImage}
          />
        </div>

        {/* Carousel Bottom Bar */}
        <div className="h-[120px] border-t border-[rgba(218,220,224,0.15)] bg-[#0e0e0e]/80 backdrop-blur-md px-4 flex items-center overflow-hidden">
          <FilterCarousel 
            activeId={activeFilterId} 
            onSelect={handleFilterChange} 
            previewImage={selectedMedia ? `data:${selectedMedia.mimeType};base64,${selectedMedia.base64}` : undefined}
          />
        </div>
      </div>

      {/* Right Controls Panel */}
      <FilterPanel 
        activeFilter={activeFilter}
        intensity={intensity}
        setIntensity={setIntensity}
        onSave={handleSave}
        isSaving={isSaving}
        hasImage={!!selectedMedia}
        onReplace={handleSelectImage}
      />
    </div>
  );
}

import React from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const RangeSlider: React.FC<{
  label: string; value: number; min: number; max: number;
  step?: number; formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))} />
    </div>
  </div>
);

import React from 'react';
import { SectionLabel, PillButton, RangeSlider } from './Primitives';
import { FilterDefinition } from '../constants';

interface FilterPanelProps {
  activeFilter: FilterDefinition;
  intensity: number;
  setIntensity: (val: number) => void;
  onSave: () => void;
  isSaving: boolean;
  hasImage: boolean;
  onReplace: () => void;
}

export const FilterPanel: React.FC<FilterPanelProps> = ({
  activeFilter,
  intensity,
  setIntensity,
  onSave,
  isSaving,
  hasImage,
  onReplace,
}) => {
  return (
    <div className="relative border-l border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between overflow-clip px-[10px] py-[12px] w-[300px] h-full min-h-0 bg-[#0e0e0e]">
      <div className="flex flex-col gap-[24px] items-start w-full">
        {/* Media Management */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Active Image</SectionLabel>
          <PillButton 
            icon={<span className="material-symbols-outlined text-[18px]">add_photo_alternate</span>} 
            variant="filled"
            onClick={onReplace}
          >
            {hasImage ? 'Replace Image' : 'Select Image'}
          </PillButton>
        </div>

        {/* Filter Details */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Filter Settings</SectionLabel>
          <div className="flex flex-col gap-4 items-start w-full px-2">
            <div className="flex flex-col gap-1">
              <span className="text-[16px] font-medium text-white">{activeFilter.label}</span>
              <span className="text-[11px] text-[rgba(218,220,224,0.5)]">Adjust the parameters below to customize the effect intensity.</span>
            </div>

            <RangeSlider 
              label={activeFilter.sliderLabel}
              value={intensity}
              min={activeFilter.min}
              max={activeFilter.max}
              step={activeFilter.step}
              formatValue={(v) => `${v}${activeFilter.unit}`}
              onChange={setIntensity}
            />
          </div>
        </div>

        {/* Filter Specs (ReadOnly Info) */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Properties</SectionLabel>
          <div className="grid grid-cols-2 gap-1 w-full">
            <div className="border border-[#595959] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none">
              <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">Mode</p>
              <span className="text-[11px] font-medium text-white tracking-[0.1px]">Real-time</span>
            </div>
            <div className="border border-[#595959] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none">
              <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">Engine</p>
              <span className="text-[11px] font-medium text-white tracking-[0.1px]">CSS GL</span>
            </div>
          </div>
        </div>
      </div>

      {/* Bottom Actions */}
      <div className="flex flex-col gap-[5px] items-start w-full pt-2">
        <PillButton 
          variant="solid" 
          icon={<span className="material-symbols-outlined text-[18px] opacity-80">download</span>}
          onClick={onSave}
          disabled={!hasImage || isSaving}
        >
          {isSaving ? 'Processing...' : 'Export to Gallery'}
        </PillButton>
      </div>
    </div>
  );
};

import React from 'react';
import { FilterType, FILTERS } from '../constants';

interface FilterCarouselProps {
  activeId: FilterType;
  onSelect: (id: FilterType) => void;
  previewImage?: string;
}

export const FilterCarousel: React.FC<FilterCarouselProps> = ({ 
  activeId, 
  onSelect, 
  previewImage 
}) => {
  return (
    <div className="w-full h-full overflow-x-auto dark-scrollbar flex items-center gap-4 px-2 no-scrollbar">
      {FILTERS.map((filter) => (
        <button
          key={filter.id}
          onClick={() => onSelect(filter.id)}
          className={`flex-shrink-0 flex flex-col items-center gap-2 group transition-all ${
            activeId === filter.id ? 'opacity-100 scale-105' : 'opacity-60 hover:opacity-100 hover:scale-102'
          }`}
        >
          <div 
            className={`w-[64px] h-[64px] rounded-xl overflow-hidden border-2 transition-colors ${
              activeId === filter.id ? 'border-white' : 'border-[#595959] group-hover:border-[#7a7a7a]'
            }`}
          >
            {previewImage ? (
              <img 
                src={previewImage} 
                alt={filter.label}
                className="w-full h-full object-cover"
                style={{ filter: filter.getStyle(filter.defaultIntensity) }}
              />
            ) : (
              <div className="w-full h-full bg-[#1a1a1a] flex items-center justify-center">
                <span className="material-symbols-outlined text-[#595959]">image</span>
              </div>
            )}
          </div>
          <span className={`text-[10px] font-medium tracking-[0.5px] uppercase transition-colors ${
            activeId === filter.id ? 'text-white' : 'text-[#595959]'
          }`}>
            {filter.label}
          </span>
        </button>
      ))}
      {/* Spacer for ending */}
      <div className="w-4 flex-shrink-0 h-full" />
    </div>
  );
};

import React from 'react';

interface ImagePreviewProps {
  media: { base64: string; mimeType: string } | null;
  filterStyle: string;
  onSelect: () => void;
}

export const ImagePreview: React.FC<ImagePreviewProps> = ({ media, filterStyle, onSelect }) => {
  if (!media) {
    return (
      <button 
        onClick={onSelect}
        className="w-full max-w-lg aspect-square border-2 border-dashed border-[#595959] hover:border-[#969696] hover:bg-white/5 transition-all rounded-3xl flex flex-col items-center justify-center gap-4 text-[rgba(255,255,255,0.4)]"
      >
        <span className="material-symbols-outlined text-[64px]">add_photo_alternate</span>
        <div className="flex flex-col items-center gap-1">
          <span className="text-[16px] font-medium text-white">Click to select an image</span>
          <span className="text-[12px]">Supports JPEG and PNG formats</span>
        </div>
      </button>
    );
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center">
      <div className="relative max-w-full max-h-full shadow-2xl shadow-black/50 rounded-lg overflow-hidden transition-all duration-300">
        <img 
          src={`data:${media.mimeType};base64,${media.base64}`} 
          alt="Preview" 
          className="max-w-full max-h-[calc(100vh-200px)] object-contain transition-all duration-150"
          style={{ filter: filterStyle }}
        />

        {/* Floating Label */}
        <div className="absolute top-4 left-4 bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10 pointer-events-none">
          <span className="text-[11px] font-medium text-white tracking-[0.5px] uppercase">Preview Mode</span>
        </div>
      </div>
    </div>
  );
};
